const cds = require('../cds')
const LOG = cds.log('ucl')

const { X509Certificate } = require('crypto')
const sdkProvider = require('../remote/utils/cloudSdkProvider')

const SSL_CLIENT_VERIFY_HEADER = 'x-ssl-client-verify'
const SSL_CLIENT_SUBJECT_HEADER = 'x-ssl-client-subject-dn'
const SSL_CLIENT_ISSUER_HEADER = 'x-ssl-client-issuer-dn'
const XFCC_HEADER = 'x-forwarded-client-cert'
const CERT_PREAMBLE = '-----BEGIN CERTIFICATE-----'
const URL_ENCODED_PREAMBLE = encodeURIComponent(CERT_PREAMBLE)
const TRUSTED_CERT = {
  CANARY: {
    ISSUER: 'CN=SAP PKI Certificate Service Client CA,OU=SAP BTP Clients,O=SAP SE,L=cf-eu10-canary,C=DE',
    SUBJECT: 'CN=cmp-stage,OU=SAP Cloud Platform Clients,OU=Canary,OU=cmp-cf-eu10-canary,O=SAP SE,L=Stage,C=DE'
  },
  LIVE: {
    ISSUER: 'CN=SAP PKI Certificate Service Client CA,OU=SAP BTP Clients,O=SAP SE,L=cf-eu10,C=DE',
    SUBJECT: 'CN=cmp-prod,OU=SAP Cloud Platform Clients,OU=cmp-cf-eu10,O=SAP SE,L=Prod,C=DE'
  }
}

const OPERATION_DEFAULT_STATES = {
  assign: 'CONFIG_PENDING',
  unassign: 'READY',
  add: 'CONFIG_PENDING',
  remove: 'CONFIG_PENDING',
  modify: 'CONFIG_PENDING',
  rotate: 'CONFIG_PENDING'
}

module.exports = class UCLService extends cds.Service {
  constructor(...args) {
    super(...args)

    // REVISIT: cds.connect.to('ucl') should return this, but no cds.requires.kinds.ucl config achieved this
    cds.services.ucl = this
  }

  async init() {
    this.on('*', 'tenantMappings', async req => {
      if (req.method !== 'PATCH') req.reject(405, `Method ${req.method} not allowed for tenant mapping notifications`)

      await this._validateCertificate(req)

      return await this._dispatchNotification(req)
    })

    if (cds.env.requires.ucl?.destination) {
      LOG.debug('Destination for asynchronous UCL callbacks configured.')

      this.after(
        Object.keys(OPERATION_DEFAULT_STATES).map(operation => `${operation}/#succeeded`),
        async (res, req) => await cds.queued(this).send('successfulMapping', { res, req })
      )
      this.after(
        Object.keys(OPERATION_DEFAULT_STATES).map(operation => `${operation}/#failed`),
        async (res, req) => await cds.queued(this).send('failedMapping', { res, req })
      )

      this.on('successfulMapping', req => this.handleSuccessfulMapping(req.data.res, req.data.req))
      this.on('failedMapping', req => this.handleFailedMapping(req.data.res, req.data.req))
    }

    await super.init()

    if (cds.env.requires.ucl?.applicationTemplate) await this._upsertApplicationTemplate(cds.env.requires.ucl)
  }

  // REVISIT: Make this configurable? Like requires[x].impl? Or the generic handlers?
  async _validateCertificate(req) {
    // Allow bypassing certificate validation during development
    if (process.env.NODE_ENV !== 'production' && cds.env.requires.ucl?.skipCertValidation) return

    let reqClientCertSubjectB64, reqClientCertIssuerB64
    // > Depend on the component that terminates TLS

    if (req.headers[SSL_CLIENT_VERIFY_HEADER]) {
      LOG.debug(`Found '${SSL_CLIENT_VERIFY_HEADER}' header: Assuming TLS termination by HAProxy.`)

      if (req.headers[SSL_CLIENT_VERIFY_HEADER] !== '0')
        cds.error(401, `Client certificate verification failed (${SSL_CLIENT_VERIFY_HEADER} is not "0")`)

      reqClientCertSubjectB64 = req.headers[SSL_CLIENT_SUBJECT_HEADER]
      if (!reqClientCertSubjectB64) return cds.error(401, `Missing ${SSL_CLIENT_SUBJECT_HEADER} header`)
      reqClientCertIssuerB64 = req.headers[SSL_CLIENT_ISSUER_HEADER]
      if (!reqClientCertIssuerB64) return cds.error(401, `Missing ${SSL_CLIENT_ISSUER_HEADER} header`)
    } else if (req.headers[XFCC_HEADER]) {
      LOG.debug(`Found '${XFCC_HEADER}' header: Assuming TLS termination by Envoy.`)

      const xfccElements = req.headers[XFCC_HEADER].split(';')
      let xfccCertElement = xfccElements
        .find(e => e.startsWith('Cert='))
        ?.replaceAll('"', '')
        ?.slice(5)
      if (!xfccCertElement) return cds.error(401, `No "Cert" field found in ${XFCC_HEADER} header`)

      if (!xfccCertElement.startsWith(CERT_PREAMBLE) && !xfccCertElement.startsWith(URL_ENCODED_PREAMBLE))
        xfccCertElement = Buffer.from(xfccCertElement, 'base64').toString()

      if (xfccCertElement.startsWith(CERT_PREAMBLE) || xfccCertElement.startsWith(URL_ENCODED_PREAMBLE)) {
        try {
          const pemCert = decodeURIComponent(xfccCertElement)
          const rawCert = pemCert.replaceAll(/-----(?:BEGIN|END) CERTIFICATE-----/g, '').replaceAll(/\s/g, '')
          const x509 = new X509Certificate(Buffer.from(rawCert, 'base64'))
          reqClientCertSubjectB64 = Buffer.from('/' + x509.subject.replaceAll('\n', '/')).toString('base64')
          reqClientCertIssuerB64 = Buffer.from('/' + x509.issuer.replaceAll('\n', '/')).toString('base64')
        } catch {
          return cds.error(401, `Failed to parse certificate in ${XFCC_HEADER} header`)
        }
      } else return cds.error(401, `Certificate in ${XFCC_HEADER} header is not a valid PEM certificate`)
    } else return cds.error(401, 'No mTLS certificate headers found')

    // Extract tokens from base64 encoded subject and issuer .cert domain headers
    const reqClientCertSubject = Buffer.from(reqClientCertSubjectB64, 'base64').toString()
    const reqClientCertSubjectTokens = reqClientCertSubject
      .replace('\n', '')
      .split('/')
      .filter(token => token)
    const reqClientCertIssuer = Buffer.from(reqClientCertIssuerB64, 'base64').toString()
    const reqClientCertIssuerTokens = reqClientCertIssuer
      .replace('\n', '')
      .split('/')
      .filter(token => token)

    // Determine trusted certificate subject and issuer information
    let trustedCertSubject = process.env.CDS_UCL_X509_CERTSUBJECT || cds.env.requires.ucl.x509?.certSubject
    let trustedCertIssuer = process.env.CDS_UCL_X509_CERTISSUER || cds.env.requires.ucl.x509?.certIssuer

    // Fall back to defaults
    if (!trustedCertIssuer?.length || !trustedCertSubject?.length) {
      let stage = 'CANARY'
      const VCAP_APPLICATION = JSON.parse(process.env.VCAP_APPLICATION || '{}')
      if (VCAP_APPLICATION.cf_api && !VCAP_APPLICATION.cf_api.endsWith('.cf.sap.hana.ondemand.com')) stage = 'LIVE'

      trustedCertIssuer = TRUSTED_CERT[stage].ISSUER
      trustedCertSubject = TRUSTED_CERT[stage].SUBJECT
    }

    // Match received with trusted info - As done in UCL reference implementation
    const matchesUclInfoSubject = trustedCertSubject
      .split(',')
      .map(token => token.trim())
      .every(token => reqClientCertSubjectTokens.includes(token))
    if (!matchesUclInfoSubject) {
      LOG.debug('Received Request Subject Info:', reqClientCertSubject)
      LOG.debug('Expected UCL Subject Info:', trustedCertSubject)
      return cds.error(401, 'Received .cert subject does not match trusted UCL info subject')
    }
    const matchesUclInfoIssuer = trustedCertIssuer
      .split(',')
      .map(token => token.trim())
      .every(token => reqClientCertIssuerTokens.includes(token))
    if (!matchesUclInfoIssuer) {
      LOG.debug('Received Request Issuer Info:', reqClientCertIssuer)
      LOG.debug('Expected UCL Issuer Info:', trustedCertIssuer)
      return cds.error(401, 'Received .cert issuer does not match trusted UCL info issuer')
    }
  }

  async _dispatchNotification(req) {
    // Call User defined handlers for tenant mapping notifications

    LOG.debug('Tenant mapping notification: ', req.data)

    const { operation } = req.data?.context ?? {}
    if (!OPERATION_DEFAULT_STATES[operation])
      return cds.error(
        400,
        `Invalid operation "${operation}" in tenant mapping notification. ` +
          `Expected one of: ${Object.keys(OPERATION_DEFAULT_STATES)
            .map(o => `"${o}"`)
            .join(', ')}.`
      )

    const locationUrl = req.headers.location
    LOG.debug(`Extracted UCL callback location from header: ${locationUrl}`)

    if (locationUrl?.length) return this._dispatchAsyncMappingNotification(req, operation, locationUrl)
    return this._dispatchSyncMappingNotification(req, operation)
  }

  async _dispatchAsyncMappingNotification(req, operation, locationUrl) {
    // Get destination based on configured destination name
    const destinationName = cds.env.requires.ucl.destination

    LOG.debug(`Callback destination configured: ${destinationName} (${typeof destinationName})`)
    if (typeof destinationName != 'string' || !destinationName?.length)
      return cds.error(500, 'UCL Notification includes location but no callback destination was configured')

    const cloudSdkConnectivity = sdkProvider.getCloudSdkConnectivity()
    const destination = await cloudSdkConnectivity.getDestination({ destinationName })
    LOG.debug(`Fetched Destination from destination service: ${destination.name}(${destination.url})`)

    // Make sure the received callback location matches the configured destination
    let destinationHost, locationHost
    try {
      locationHost = new URL(locationUrl).host
    } catch (e) {
      return cds.error(400, `Failed parsing URL in location header: ${e.message}`)
    }
    try {
      destinationHost = new URL(destination.url).host
    } catch (e) {
      return cds.error(500, `Failed parsing URL in destination "${destinationName}": ${e.message}`)
    }
    if (locationHost !== destinationHost) {
      return cds.error(
        400,
        `Host mismatch: locationUrl host (${locationHost}) does not match destination.url host (${destinationHost})`
      )
    }

    const receiverTenantId = req.data?.receiverTenant?.applicationTenantId
    LOG.debug(`Handling '${operation}' asynchronously, as tenant: ${receiverTenantId}`)

    LOG.debug(`Established destination host for UCL callbacks: ${destinationHost}`)
    LOG.debug(`Established intended UCL callback host from location header: ${locationHost}`)

    // Schedule the tenant mapping task
    await cds.tx({ tenant: receiverTenantId }, async () => {
      await cds.queued(this).send(operation, req.data, req.headers)
    })

    LOG.debug(`Successfully dispatched '${operation}' operation for: ${receiverTenantId}`)

    req.http.res.status(202) // Respond '202: Accepted' to UCL
    return
  }

  async _dispatchSyncMappingNotification(req, operation) {
    const receiverTenantId = req.data?.receiverTenant?.applicationTenantId
    LOG.debug(`Handling '${operation}' synchronously, as tenant: ${receiverTenantId}`)

    const response = (await cds.tx({ tenant: receiverTenantId }, async () => this.send(operation, req.data))) ?? {}
    if (response.error) req.http.res.status(400)
    else response.state ??= OPERATION_DEFAULT_STATES[operation]
    return response
  }

  async handleSuccessfulMapping(callbackResult, tenantMapping) {
    const { operation, operationId } = tenantMapping.data.context
    if (!callbackResult) callbackResult = {}

    LOG.debug(`UCL ${operation} operation succeeded with result:`, callbackResult)

    // SPII v3 (operationId exists) vs v2
    const method = operationId ? 'PUT' : 'PATCH'

    const data = {
      ...callbackResult,
      state: callbackResult.state ?? OPERATION_DEFAULT_STATES[operation]
    }

    const cloudSdkHttpClient = sdkProvider.getCloudSdk()
    const response = await cloudSdkHttpClient.executeHttpRequest(
      { destinationName: cds.env.requires.ucl.destination },
      { method, url: tenantMapping.headers.location, data },
      { fetchCsrfToken: false }
    )

    if (response.status >= 500)
      cds.error(`Callback to UCL for successful ${operation} operation failed: ${response.data.error}`)
    if (response.status >= 400)
      cds.error(`UCL rejected successful ${operation} operation callback: ${response.data.error}`, {
        unrecoverable: true
      })

    LOG.debug(`UCL Callback completed with status: ${response.status}`)
  }

  async handleFailedMapping(callbackError, tenantMapping) {
    const { operation, operationId } = tenantMapping.data.context

    LOG.error(`UCL ${operation} operation failed:`, callbackError, tenantMapping)

    // SPII v3 (operationId exists) vs v2
    const method = operationId ? 'PUT' : 'PATCH'

    const cloudSdkHttpClient = sdkProvider.getCloudSdk()
    const response = await cloudSdkHttpClient.executeHttpRequest(
      { destinationName: cds.env.requires.ucl.destination },
      { method, url: tenantMapping.headers.location, data: { state: 'ERROR' } },
      { fetchCsrfToken: false }
    )

    if (response.status >= 500)
      cds.error(`Callback to UCL for failed ${operation} operation failed: ${response.data.error}`)
    if (response.status >= 400)
      cds.error(`UCL rejected failed ${operation} operation callback: ${response.data.error}`, {
        unrecoverable: true
      })

    LOG.debug(`UCL Callback completed with status: ${response.status}`)
  }
}
